const store = $getWorkflowStaticData('global');
store.food99FinanceTokens = store.food99FinanceTokens || {};
const cached = store.food99FinanceTokens[$json.api_key];
const valido = !!(cached && cached.expiresAt > Date.now() + 60000);
return [{ json: { ...$json, access_token: valido ? cached.accessToken : null, token_valido: valido } }];

const ctx = $('Checar token financeiro em cache').item.json;
const resp = $json;
const ok = !!resp.accessToken;
const store = $getWorkflowStaticData('global');
store.food99FinanceTokens = store.food99FinanceTokens || {};
if (ok) { store.food99FinanceTokens[ctx.api_key] = { accessToken: resp.accessToken, expiresAt: Date.now() + ((resp.expiresIn || 21600) * 1000) }; }
return [{ json: { ...ctx, access_token: ok ? resp.accessToken : null, token_valido: ok, token_erro: ok ? null : (resp.errmsg || 'erro desconhecido ao obter token financeiro') } }];

const now = new Date();
const end = new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000);
const begin = new Date(end.getTime() - 6 * 24 * 60 * 60 * 1000);
const fmt = (d) => d.toISOString().slice(0, 10).replace(/-/g, '');
return [{ json: { ...$json, start_date: fmt(begin), end_date: fmt(end) } }];

const rows = ($json.data && $json.data.data) || [];
// So linhas de receita/reembolso de pedido tem orderId util pra casar com
// marketplace_pedidos -- orderType 5 (taxa mensal/nao-acompanhante) nao tem
// order_id de verdade, pula.
return rows.filter(r => r.orderId && r.orderType !== 5).map(r => ({
  json: {
    marketplace_order_id: String(r.orderId),
    valor_bruto: (r.orderAmount || 0) / 100,
    taxa_comissao: (r.commissionAmount || 0) / 100,
    taxa_gateway: (r.payCommissionAmount || 0) / 100,
    taxa_entrega_marketplace: (r.b2pDeliveryAmount || 0) / 100,
    valor_liquido_recebido: (r.settlementAmount || 0) / 100,
    data_prevista_repassado: r.expectSettleDate || null,
    linha_bruta: JSON.stringify(r),
  },
}));
